function SecHead({ n, t, d }) {
  return (<div className="ps-sec-head"><span className="ps-sec-num">{n}</span><h2>{t}</h2>{d && <p>{d}</p>}</div>);
}

function Chip({ estado, nota }) {
  const ok = estado === "corroborada";
  return (
    <span className={"ps-chip " + (ok ? "ps-chip-ok" : "ps-chip-no")} title={nota || ""}>
      {ok ? "corroborada" : "no confirmada"}
    </span>
  );
}

function Hecho({ h }) {
  return (
    <div className="ps-hecho">
      <div className="ps-hecho-top"><Chip estado={h.confianza} nota={h.nota} /><span className="ps-hecho-fuente">{h.fuente}</span></div>
      <p>{h.afirmacion}</p>
      {h.nota && <p className="ps-hecho-nota">{h.nota}</p>}
    </div>
  );
}

function LineaTiempo({ eventos }) {
  return (
    <div className="ps-timeline">
      {eventos.map((e, i) => {
        const vacio = e.estado === "vacio_informativo";
        return (
          <div className="ps-tl-row" key={i}>
            <div className="ps-tl-axis">
              <span className={"ps-tl-dot" + (vacio ? " ps-tl-dot-vacio" : "")} />
              {i < eventos.length - 1 && <span className={"ps-tl-conn" + (vacio ? " ps-tl-conn-vacio" : "")} />}
            </div>
            <div className="ps-tl-body">
              <div className="ps-tl-fecha">{e.fecha} <span className="ps-tl-estado">{ESTADO_LABEL[e.estado]}</span></div>
              <p>{e.detalle}</p>
              <div className="ps-tl-meta"><Chip estado={e.confianza} nota={e.nota} /><span className="ps-tl-fuente">{e.fuente}</span></div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function MapaProvincias({ puntos }) {
  const [hover, setHover] = useState(null);
  const byProv = {};
  puntos.forEach((p) => { byProv[p.provincia] = p; });
  const sel = hover && byProv[hover];
  return (
    <div className="ps-mapawrap">
      <svg viewBox="0 0 774.25848 264.93973" className="ps-map" role="img" aria-label="Mapa de Cuba: caso indice y casos comparables por provincia">
        {Object.keys(PROV_GEO).map((prov) => {
          const p = byProv[prov];
          const on = hover === prov;
          const fill = p ? ROL_COLOR[p.rol] : C.dim;
          return (
            <path key={prov} d={PROV_GEO[prov]} fill={fill}
              fillOpacity={p ? (on ? 0.95 : 0.62) : 0.10}
              stroke={on ? C.paper : "rgba(60,40,20,.28)"} strokeWidth={on ? 1.4 : 0.5}
              style={{ cursor: p ? "pointer" : "default", transition: "fill-opacity .15s ease" }}
              onMouseEnter={() => p && setHover(prov)} onMouseLeave={() => setHover(null)}>
              <title>{p ? prov + " — " + p.detalle : prov}</title>
            </path>
          );
        })}
      </svg>
      <div className="ps-mapa-legend">
        <span><i style={{ background: C.indigo }} /> Caso indice</span>
        <span><i style={{ background: C.oliva }} /> Patron comparable</span>
      </div>
      {sel && <div className="ps-mapa-readout"><b>{hover}</b><p>{sel.detalle}</p></div>}
    </div>
  );
}

function Radar({ ejes, series }) {
  const R = 90, CX = 110, CY = 100, MAX = 3;
  const angle = (i) => (Math.PI * 2 * i) / ejes.length - Math.PI / 2;
  const pt = (i, v) => {
    const r = (v / MAX) * R;
    return [CX + r * Math.cos(angle(i)), CY + r * Math.sin(angle(i))];
  };
  const colores = [C.indigo, C.oliva, "#B87C14", "#2F7FB0"];
  const rings = [1, 2, 3];
  return (
    <div className="ps-radar-wrap">
      <svg viewBox="0 0 220 200" className="ps-radar-svg">
        {rings.map((r) => (
          <polygon key={r} points={ejes.map((_, i) => pt(i, r).join(",")).join(" ")}
            fill="none" stroke={C.line} strokeWidth="1" />
        ))}
        {ejes.map((_, i) => {
          const [x, y] = pt(i, MAX);
          return <line key={i} x1={CX} y1={CY} x2={x} y2={y} stroke={C.line} strokeWidth="1" />;
        })}
        {series.map((s, si) => (
          <polygon key={s.nombre} points={s.valores.map((v, i) => pt(i, v).join(",")).join(" ")}
            fill={colores[si % colores.length]} fillOpacity="0.16"
            stroke={colores[si % colores.length]} strokeWidth="2" />
        ))}
        {ejes.map((e, i) => {
          const [x, y] = pt(i, MAX + 0.55);
          return (
            <text key={e} x={x} y={y} fontSize="8" fill={C.dim} textAnchor="middle" dominantBaseline="middle">
              {e.length > 22 ? e.slice(0, 20) + "…" : e}
            </text>
          );
        })}
      </svg>
      <ul className="ps-radar-legend">
        {series.map((s, si) => (
          <li key={s.nombre}><i style={{ background: colores[si % colores.length] }} /> {s.nombre}</li>
        ))}
      </ul>
    </div>
  );
}

function DotPlotRango({ casos }) {
  const MAXA = 10;
  return (
    <div className="ps-dotplot">
      {casos.map((c) => {
        const pendiente = c.condena_anios_min == null && c.condena_anios_max == null;
        const min = c.condena_anios_min == null ? 0 : c.condena_anios_min;
        const max = c.condena_anios_max == null ? min : c.condena_anios_max;
        return (
          <div className="ps-dot-row" key={c.nombre}>
            <span className="ps-dot-label">{c.nombre}<i>{c.provincia} · {c.fecha}</i></span>
            <span className="ps-dot-track">
              {pendiente ? (
                <span className="ps-dot-pendiente">proceso en curso — {c.condena}</span>
              ) : (
                <span className="ps-dot-range" style={{ left: (min / MAXA) * 100 + "%", width: Math.max(2, ((max - min) / MAXA) * 100) + "%" }}>
                  <b>{c.condena}</b>
                </span>
              )}
            </span>
            <Chip estado={c.confianza} nota={c.fuente} />
          </div>
        );
      })}
    </div>
  );
}

function GaugeRadial({ label, value, max, sub, color }) {
  const pct = Math.min(1, value / max);
  const R = 46, C_ = 2 * Math.PI * R;
  return (
    <div className="ps-gauge">
      <svg viewBox="0 0 120 120" className="ps-gauge-svg">
        <circle cx="60" cy="60" r={R} fill="none" stroke={C.panel2} strokeWidth="10" />
        <circle cx="60" cy="60" r={R} fill="none" stroke={color} strokeWidth="10"
          strokeDasharray={C_} strokeDashoffset={C_ * (1 - pct)} strokeLinecap="round"
          transform="rotate(-90 60 60)" />
        <text x="60" y="56" textAnchor="middle" fontSize="22" fill={C.paper} fontFamily="'IBM Plex Mono',monospace">{value}</text>
        <text x="60" y="74" textAnchor="middle" fontSize="9" fill={C.dim}>/ {max}</text>
      </svg>
      <p className="ps-gauge-label"><b>{label}</b>{sub}</p>
    </div>
  );
}

function Encuesta({ datos }) {
  const CLAVE = "yamacoa_protesta_solitaria_votos";
  const [votos, setVotos] = useState({});
  const [miVoto, setMiVoto] = useState({});
  useEffect(() => {
    try {
      const local = JSON.parse(localStorage.getItem(CLAVE) || "{}");
      setVotos(local.votos || {});
      setMiVoto(local.miVoto || {});
    } catch (e) {}
    const sb = typeof window !== "undefined" && window.__yamacoaSupabase;
    if (sb && sb.rpc) {
      sb.rpc("protesta_solitaria_totales").then(({ data }) => { if (data) setVotos((v) => ({ ...v, ...data })); }).catch(() => {});
    }
  }, []);
  const votar = (pid, opcion) => {
    if (miVoto[pid] != null) return;
    setVotos((prev) => {
      const p = { ...(prev[pid] || {}) };
      p[opcion] = (p[opcion] || 0) + 1;
      const nuevos = { ...prev, [pid]: p };
      const nuevoMi = { ...miVoto, [pid]: opcion };
      try { localStorage.setItem(CLAVE, JSON.stringify({ votos: nuevos, miVoto: nuevoMi })); } catch (e) {}
      return nuevos;
    });
    setMiVoto((m) => ({ ...m, [pid]: opcion }));
    const sb = typeof window !== "undefined" && window.__yamacoaSupabase;
    if (sb && sb.rpc) sb.rpc("protesta_solitaria_votar", { p_pregunta: pid, p_opcion: opcion }).catch(() => {});
  };
  return (
    <div className="ps-encuesta">
      {datos.preguntas.map((q) => {
        const conteo = votos[q.id] || {};
        const total = Object.values(conteo).reduce((a, b) => a + b, 0);
        const votado = miVoto[q.id] != null;
        return (
          <div className="ps-pregunta" key={q.id}>
            <p>{q.texto}</p>
            {q.opciones.map((op) => {
              const n = conteo[op] || 0;
              const pct = total ? Math.round((n / total) * 100) : 0;
              const elegida = miVoto[q.id] === op;
              return (
                <button key={op} className="ps-opcion" disabled={votado} onClick={() => votar(q.id, op)}>
                  <span className="ps-opcion-fill" style={{ width: votado ? pct + "%" : 0, background: elegida ? "rgba(85,72,174,.20)" : "rgba(107,93,80,.12)" }} />
                  <span className="ps-opcion-txt"><span>{elegida ? "✓ " : ""}{op}</span>{votado && <span>{pct}%</span>}</span>
                </button>
              );
            })}
            <p className="ps-pregunta-total">{total} voto{total === 1 ? "" : "s"}</p>
          </div>
        );
      })}
    </div>
  );
}

function Donut({ corroboradas, no_confirmadas, excluidas }) {
  const total = corroboradas + no_confirmadas + excluidas;
  const a = (corroboradas / total) * 360;
  const b = (no_confirmadas / total) * 360;
  const grad = `conic-gradient(${C.corrob} 0deg ${a}deg, ${C.noconf} ${a}deg ${a + b}deg, ${C.dim} ${a + b}deg 360deg)`;
  return (
    <div className="ps-donut-wrap">
      <div className="ps-donut" style={{ background: grad }}>
        <div className="ps-donut-hole"><b>{total}</b><span>evaluadas</span></div>
      </div>
      <ul className="ps-donut-legend">
        <li><i style={{ background: C.corrob }} /> {corroboradas} corroboradas</li>
        <li><i style={{ background: C.noconf }} /> {no_confirmadas} no confirmadas</li>
        <li><i style={{ background: C.dim }} /> {excluidas} excluidas</li>
      </ul>
    </div>
  );
}

